{
  "spells": [
    {
      "id": "spell_life_10",
      "theory": "净创术将魔力导入草药捣成的湿敷泥中，使泥内的细粒沿创面沟壑游走，吸附常见的尘土与腐屑。毒素与异物不受此术影响，仍需另行处理。泥层须保持湿润，干涸后魔力散逸，清洁作用随之中止。",
      "casting": "取一份草药嚼碎或捣成泥，用掌心托住敷在创面，另一手食指沿创缘顺时针画三圈，同时缓缓注入魔力。",
      "failure": "泥层会突然干裂成粉，从创面剥落，只留下未清除的污物。若魔力注入过快，创缘会泛起一圈红痕，需等红痕消退后再试。",
      "counters": [
        "用大量清水冲洗创面，冲散泥层，使魔力无处依附。",
        "以干净布片覆盖创面，阻断泥层与空气接触，加速其干涸失效。"
      ],
      "socialConsequences": "乡间农户常请略通此术的人处理田间擦伤，酬以草药或饭食。镇上药铺掌柜乐于收购干净草药，但担心此术减少外敷药膏的销路。施术者若在他人身上使用，须先说明泥层可能干裂，并征得对方同意；在河岸村落，给陌生人处理伤口前最好有乡约见证，以免日后争执。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常因泥层干裂而重复敷药，清洁范围也难控制。",
        "百点后泥层能保持湿润至术毕，创缘红痕明显减少。",
        "三百点后能均匀铺泥，使清洁覆盖整个创面而不遗漏边角。",
        "六百点后泥层干裂前即可完成，动作稳定，几乎不再泛红。"
      ]
    },
    {
      "id": "spell_life_11",
      "theory": "嫁枝契将魔力沿砧木与接穗的形成层传递，使两侧细胞暂时软化并相互贴合，从而降低排异。此术要求两株植物亲缘兼容，且切口平整；若形成层错位，魔力便会在缝隙处散失，无法促成接合。",
      "casting": "用园艺刀削出平整斜面，将接穗与砧木形成层对齐，以拇指按住接合处，另一手食指沿接缝画一道短竖线并注入魔力。",
      "failure": "接合处会渗出淡色汁液，接穗在数日内枯萎，砧木切口发黑。若魔力过强，接穗表皮会起皱，即使暂时贴合也会在日后断裂。",
      "counters": [
        "用湿布包裹接合处，隔绝空气，使魔力无法沿形成层传递。",
        "将接穗轻轻拔离砧木，重新对齐形成层后再行尝试。"
      ],
      "socialConsequences": "果园与苗圃的园艺师看重此术，愿以树苗或工时交换施术。贩卖现成嫁接苗的商贩担心此术普及后苗价下跌，便强调兼容植株与手艺的重要性。在河岸村落，替邻家果树嫁接通常由乡约见证口头约定，明确成活后如何分成；若在他人园中施术而未获许可，园主可依乡约要求赔偿。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常因形成层错位而失败，接穗数日内便枯萎。",
        "百点后能较准地对齐形成层，接合处汁液渗出减少。",
        "三百点后动作稳定，接穗表皮极少起皱，成活率提高。",
        "六百点后可在接合处均匀传递魔力，几乎不伤及周围树皮。"
      ]
    },
    {
      "id": "spell_life_12",
      "theory": "驱蛊纹以魔力在皮肤表面画出螺旋纹路，使纹路内的魔力缓缓渗入皮下，刺激寄生物向纹路中心移动，最终随体液排出。此术只能作用于可识别的小型寄生物，对深藏脏腑者无效，且可能伤及宿主。",
      "casting": "以指尖蘸取草药汁，在寄生物附近皮肤上画一道由外向内收拢的螺旋，画毕将掌心覆于螺旋中心，持续注入魔力至纹路微微发热。",
      "failure": "螺旋纹路会中途断裂，寄生物受惊后向更深处钻入，宿主感到一阵刺痛。若魔力注入过猛，纹路周围会浮现大片红疹，需数日方能消退。",
      "counters": [
        "用酒或醋擦洗皮肤，溶解草药汁，使纹路失去依附。",
        "以热布敷在纹路处，迫使寄生物停止移动并退回原处。"
      ],
      "socialConsequences": "在河岸营地，有人被水蛭或小虫侵扰时，会请通此术者帮忙，事后赠以鱼干或草药。城中公会要求施术者登记，以便追踪是否伤及宿主；若在港口替船员驱虫，港务会查看是否因操作不当导致货损或船员无法上工。未经同意在他人身上画纹，会被视为侵犯身体，乡约与港务均可追究。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常画断螺旋，寄生物受惊钻深，宿主疼痛加剧。",
        "百点后纹路能完整闭合，寄生物排出时宿主仅感轻微酸胀。",
        "三百点后能控制魔力渗入速度，红疹范围明显缩小。",
        "六百点后动作精准，寄生物随体液排出，宿主皮肤仅留浅痕。"
      ]
    }
  ]
}
